import json
from fractions import Fraction

age = Fraction(3, 2)
money = {"basenji": 90, "swan": 58, "german shepherd": 57}
names = {"basenji": "Milo", "seahorse": "Meadow"}

# Only predicates relevant to the queried conclusion are needed.
facts = set()
if age < 4:
    facts.add(("under_four", "basenji"))
if names["basenji"][0] == names["seahorse"][0]:
    facts.add(("matching_initial", "basenji"))
if money["basenji"] > money["swan"] + money["german shepherd"]:
    facts.add(("richer_than_combined", "basenji"))

# No initial fact states that any animal neglects the swan, and no
# rule has such a fact as its conclusion.
neglect_witnesses = set()

rules = [
    ("Rule2", {("under_four", "basenji")},
     ("company_badger", "basenji")),
    ("Rule3", {("matching_initial", "basenji")},
     ("convince_seal", "basenji")),
    ("Rule4", {("richer_than_combined", "basenji")},
     ("company_badger", "basenji")),
    ("Rule5", {("exists_neglect_swan",)},
     ("not_borrow_bulldog", "basenji")),
    ("Rule7", {
        ("convince_seal", "basenji"),
        ("company_badger", "basenji"),
    }, ("borrow_bulldog", "basenji")),
]

if neglect_witnesses:
    facts.add(("exists_neglect_swan",))

support = {}
changed = True
while changed:
    changed = False
    for rule, antecedents, conclusion in rules:
        if antecedents <= facts:
            support.setdefault(conclusion, set()).add(rule)
            if conclusion not in facts:
                facts.add(conclusion)
                changed = True

positive = ("borrow_bulldog", "basenji")
negative = ("not_borrow_bulldog", "basenji")
positive_supported = positive in facts
negative_supported = negative in facts

# Apply the stated priority only when both conflicting rules apply.
if positive_supported and negative_supported:
    if ("Rule5" in support.get(negative, set())
            and "Rule7" in support.get(positive, set())):
        positive_supported = False
    else:
        print("UNSUPPORTED")
        raise SystemExit

answer = (
    "proved" if positive_supported else
    "disproved" if negative_supported else
    "unknown"
)

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "age": str(age),
        "age_less_than_four": age < 4,
        "name_initials": [names["basenji"][0], names["seahorse"][0]],
        "matching_initials": names["basenji"][0] == names["seahorse"][0],
        "money_exceeds_combined": (
            money["basenji"] > money["swan"] + money["german shepherd"]
        ),
        "neglect_swan_witnesses": sorted(neglect_witnesses),
        "positive_support": sorted(support.get(positive, set())),
        "negative_support": sorted(support.get(negative, set()))
    }
}, separators=(",", ":")))
